"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[3169],{45705:e=>{e.exports=JSON.parse('{"functions":[{"name":"if","desc":"C-style branch. `else if` emits Luau `elseif`. Parentheses required. No ternary.\\n\\n**Syntax:** `if (cond) { } else if (other) { } else { }`\\n\\n**Emit:** `if` / `elseif` / `else` / `end`","params":[],"returns":[],"function_type":"static","tags":["control"],"source":{"line":21,"path":"moonwave/ControlFlow.lua"}},{"name":"while","desc":"Loop while the condition is true. No `do/while`. No `continue`.\\n\\n**Syntax:** `while (cond) { }`\\n\\n**Emit:** `while \u2026 do \u2026 end`","params":[],"returns":[],"function_type":"static","tags":["control"],"source":{"line":33,"path":"moonwave/ControlFlow.lua"}},{"name":"for","desc":"C `for`. Emits `while` plus a trailing increment. Semicolons separate clauses.\\n\\n**Syntax:** `for (int i = 0; i < n; i++) { }`\\n\\n**Emit:** `local i = 0` / `while i < n do` / `i += 1`","params":[],"returns":[],"function_type":"static","tags":["control"],"source":{"line":45,"path":"moonwave/ControlFlow.lua"}},{"name":"for-in","desc":"Range-for. Prefer `in`. The C++-style `:` is the same loop, not a table key.\\n\\n**Syntax:** `for (T x in list) { }` \xb7 `for (T x in list) { }`\\n\\n**Emit:** `for _, x in list do`\\n\\n```clpp\\nfor (Player player in players.GetPlayers()) {\\n    post(player.Name);\\n}\\n```","params":[],"returns":[],"function_type":"static","tags":["control"],"source":{"line":63,"path":"moonwave/ControlFlow.lua"}},{"name":"guard","desc":"If the condition is false, the `else` block runs (usually `return`). The `else` is required.\\n\\n**Syntax:** `guard (condition) else { return; }`\\n\\n**Emit:** `if not (condition) then \u2026 end`\\n\\n```clpp\\nguard (player != null) else {\\n    warn(\\"Invalid player\\");\\n    return;\\n}\\n```","params":[],"returns":[],"function_type":"static","tags":["control"],"source":{"line":82,"path":"moonwave/ControlFlow.lua"}},{"name":"match","desc":"Type switch. Instance types use `IsA`; primitives use `typeof`. `_` is the fallback.\\n\\n**Syntax:** `match (value) { Type name => stmt, _ => stmt };`\\n\\n**Emit:** `if x:IsA(\\"Type\\") then` / `typeof`\\n\\nArms are a class or primitive name (`Part p`, `string s`) \u2014 not a C++ pointer.\\n\\n```clpp\\nmatch (instance) {\\n    Part p => p.BrickColor = BrickColor::Red(),\\n    _ => warn(\\"unsupported\\")\\n};\\n```","params":[],"returns":[],"function_type":"static","tags":["control"],"source":{"line":103,"path":"moonwave/ControlFlow.lua"}},{"name":"switch","desc":"Evaluates the discriminant once. `break` leaves the switch. No C fall-through; stacked `case`s share a body.\\n\\n**Syntax:** `switch (action) { case \\"buy\\": \u2026 break; default: \u2026 break; }`\\n\\n**Emit:** `if` / `elseif` inside `repeat \u2026 until true`","params":[],"returns":[],"function_type":"static","tags":["control"],"source":{"line":115,"path":"moonwave/ControlFlow.lua"}},{"name":"break","desc":"Leaves the innermost loop or `switch`. There is no `continue`.\\n\\n**Syntax:** `break;`\\n\\n**Emit:** `break`","params":[],"returns":[],"function_type":"static","tags":["control"],"source":{"line":127,"path":"moonwave/ControlFlow.lua"}},{"name":"return","desc":"Leave the current function.\\n\\n**Syntax:** `return;` \xb7 `return expr;`\\n\\n**Emit:** `return` / `return expr`","params":[],"returns":[],"function_type":"static","tags":["control"],"source":{"line":139,"path":"moonwave/ControlFlow.lua"}}],"properties":[],"types":[],"name":"ControlFlow","desc":"Branching, loops, `guard`, `match`, and `switch`.\\n\\nThere is no `continue`, ternary `? :`, or `do/while`. Full pages: [if](/CLPP/docs/reference/if), [guard](/CLPP/docs/reference/guard), [match](/CLPP/docs/reference/match).","source":{"line":9,"path":"moonwave/ControlFlow.lua"}}')}}]);